body:
I did manage to hunt down the problem to be `DisplayServerWindows::screen_get_usable_rect()` always returning the "work area" of the screen, rather than the full screen area if needed. This causes problems at two places:
```c++
// scene/main/window.cpp Window::popup()
Rect2i adjust = _popup_adjust_rect(); // will adjust according to screen usable rect eventually
if (adjust != Rect2i()) {
	set_position(adjust.position);
	set_size(adjust.size);
}

// platform/windows/display_server_windows.cpp DisplayServerWindows::_create_window()
if (p_mode == WINDOW_MODE_MAXIMIZED && (p_flags & WINDOW_FLAG_BORDERLESS_BIT)) {
	Rect2i srect = screen_get_usable_rect(rq_screen); // popup window set to be at origin of screen usable rect
	SetWindowPos(wd.hWnd, HWND_TOP, srect.position.x, srect.position.y, srect.size.width, srect.size.height, SWP_NOZORDER | SWP_NOACTIVATE);
}

```

A workaround is to modify `DisplayServerWindows::screen_get_usable_rect()` so that it checks if the editor is in fullscreen mode and return the full screen size in that case. Feels like a hack, since I'm not sure if "get_usable_rect" can mean this.
```diff
diff --git a/platform/windows/display_server_windows.cpp b/platform/windows/display_server_windows.cpp
index 74d651d495..3c8a8bec20 100644
--- a/platform/windows/display_server_windows.cpp
+++ b/platform/windows/display_server_windows.cpp
@@ -1097,6 +1097,7 @@ typedef struct {
        int count;
        int screen;
        Rect2i rect;
+       bool use_work_area;
 } EnumRectData;

 typedef struct {
@@ -1135,10 +1136,17 @@ static BOOL CALLBACK _MonitorEnumProcUsableSize(HMONITOR hMonitor, HDC hdcMonito
                minfo.cbSize = sizeof(MONITORINFO);
                GetMonitorInfoA(hMonitor, &minfo);

-               data->rect.position.x = minfo.rcWork.left;
-               data->rect.position.y = minfo.rcWork.top;
-               data->rect.size.x = minfo.rcWork.right - minfo.rcWork.left;
-               data->rect.size.y = minfo.rcWork.bottom - minfo.rcWork.top;
+               if (data->use_work_area) {
+                       data->rect.position.x = minfo.rcWork.left;
+                       data->rect.position.y = minfo.rcWork.top;
+                       data->rect.size.x = minfo.rcWork.right - minfo.rcWork.left;
+                       data->rect.size.y = minfo.rcWork.bottom - minfo.rcWork.top;
+               } else {
+                       data->rect.position.x = minfo.rcMonitor.left;
+                       data->rect.position.y = minfo.rcMonitor.top;
+                       data->rect.size.x = minfo.rcMonitor.right - minfo.rcMonitor.left;
+                       data->rect.size.y = minfo.rcMonitor.bottom - minfo.rcMonitor.top;
+               }
        }

        data->count++;
@@ -1186,8 +1194,13 @@ static BOOL CALLBACK _MonitorEnumProcRefreshRate(HMONITOR hMonitor, HDC hdcMonit
 Rect2i DisplayServerWindows::screen_get_usable_rect(int p_screen) const {
        _THREAD_SAFE_METHOD_

+       bool fullscreen = false;
+       if (windows.has(MAIN_WINDOW_ID)) {
+               fullscreen = windows[MAIN_WINDOW_ID].fullscreen;
+       }
+
        p_screen = _get_screen_index(p_screen);
-       EnumRectData data = { 0, p_screen, Rect2i() };
+       EnumRectData data = { 0, p_screen, Rect2i(), !fullscreen };
        EnumDisplayMonitors(nullptr, nullptr, _MonitorEnumProcUsableSize, (LPARAM)&data);
        data.rect.position -= _get_screens_origin();
        return data.rect;
```
